function Read-Tree { for ($t = 1; $t -le 4; $t++) { $r = (npx wrangler kv key get --namespace-id $ns "card:tree" --remote 2>$null | Out-String).Trim(); if ($r.StartsWith("{")) { try { $o = $r | ConvertFrom-Json; if ($o.subjects -and $o.specific) { return @{ raw = $r; tree = $o } } } catch {} }; "  read failed (try " + $t + ") - retrying"; Start-Sleep -Seconds 5 }; return $null }
$slug = { param($x) $s = (($x.ToLower() -replace "[^a-z0-9]+","-").Trim("-")); if ($s.Length -gt 70) { $s = $s.Substring(0,70) }; $s }
$got = Read-Tree
if (-not $got) { "COULD NOT READ THE CATALOG - nothing written, run the block again" } else {
$tt = $got.tree
$backup = Join-Path $env:TEMP ("card-tree-backup-" + (Get-Date -Format "yyyyMMdd-HHmmss") + ".json")
[System.IO.File]::WriteAllText($backup, $got.raw, (New-Object System.Text.UTF8Encoding $false))
"  backup of the catalog saved first: " + $backup
$beforeCats = @($tt.subjects.PSObject.Properties).Count
$cats = [ordered]@{}
$b = @{}
$test = @{}
$cats['Skulls & Skeletons'] = [ordered]@{}
$test['Skulls & Skeletons'] = 'An anatomically observed human skull is shown from an unusual three-quarter underside angle so the jaw teeth cheekbone and base of the cranium become the composition. Fine Black and Grey rendering treats the skull like a beautiful anatomical study rather than a death emblem'
$cats['Skulls & Skeletons']['Skulls & Skeletons The Skull'] = @('An anatomically observed human skull is shown from an unusual three-quarter underside angle so the jaw teeth cheekbone and base of the cranium become the composition. Fine Black and Grey rendering treats the skull like a beautiful anatomical study rather than a death emblem','A human skull is seen directly from above. The unusual viewpoint turns the cranium into a broad sculptural form while the eye sockets are barely visible below','A skull lies on its side as though placed naturally on a table rather than arranged as an emblem. Warm directional light crosses the bone while the opposite side disappears into deep shadow','A skull is rendered through Fine Line anatomical drawing with small construction marks proportion guides and selected labels implied as part of the visual language without unnecessary text','A skull turns sharply upward with the jaw slightly open. Extreme foreshortening enlarges the teeth and jaw while the cranium recedes dramatically','A human skull is built entirely from controlled Dotwork. Dense points create the deepest sockets while the brightest bone remains almost untouched skin','A cracked skull is reconstructed through visible golden structural lines that follow the actual fractures rather than coating the entire skull decoratively. Bone remains ivory and black while gold appears only where the form has broken','A skull is sliced visually into five horizontal anatomical layers. Each layer remains perfectly aligned but floats a small distance from the next exposing impossible empty space between sections','A skull emerges from darkness with only one eye socket the nasal cavity several teeth and the nearest cheekbone receiving light. Most of the cranium is never explicitly outlined','A human skull is rendered at nearly life size with extraordinary Colour Realism created entirely by environmental light. Cobalt light hits one side while deep crimson light touches the opposite side yet the bone itself remains naturally ivory')
$cats['Skulls & Skeletons']['Skulls & Skeletons The Skeleton'] = @('A complete human skeleton sits on the edge of an invisible bed with elbows resting on knees and head lowered. Nothing else is required because the posture alone communicates exhaustion and loneliness','Two skeletons stand forehead to forehead with hands resting gently around each others rib cages. Fine Line anatomy and restrained Dotwork create intimacy without needing facial expressions','A skeleton lies peacefully on its back in tall grass with both hands resting over the ribs. Small plants grow naturally around and between the bones without turning the figure into a floral skull cliche','A skeleton stands upright beneath heavy rain with the skull tilted upward. Water streams along the ribs pelvis and limbs allowing Colour Realism reflections to make pale bone feel wet','A skeleton curls tightly into a fetal position. The spine pelvis and limbs create an almost circular anatomical composition','A skeleton reaches upward with one arm fully extended while the body stretches through the entire vertical composition. The gesture feels desperate without requiring any supernatural environment','A skeleton kneels with its hands resting loosely on its thighs and head slightly bowed. Engraving treatment gives the simple posture the gravity of an old illustration','A skeleton reclines casually with one knee raised and one arm behind its skull. The pose feels relaxed and strangely human without turning into comedy','A skeleton carries another complete skeleton across its arms. The weight of the second body visibly affects the posture of the first making the composition about burden and care','A skeleton stands in profile holding its own skull in both hands while its actual neck ends naturally at the upper vertebrae. The image is surreal but rendered with anatomical discipline')
$cats['Skulls & Skeletons']['Skulls & Skeletons Bone Anatomy and The Body'] = @('An anatomically accurate skeletal hand aligns over the wearers actual hand and wrist. Each tattooed bone follows the underlying finger structure as closely as practical creating an X-ray-like relationship with the real anatomy','Cervical and upper thoracic vertebrae follow the wearers actual spine with Fine Line anatomical precision. Soft Dotwork shadows create enough depth to separate each vertebra without turning the design into an X-ray graphic','A rib cage is drawn across one side of the torso so tattooed ribs interact visually with the wearers real rib structure. Parts are deliberately omitted so the composition remains open and breathable','A skeletal foot is aligned across the top of the actual foot. Fine Line anatomy emphasizes the long metatarsals and individual toe bones','A pelvis is rendered as an elegant symmetrical anatomical study. Rather than presenting it like a medical diagram subtle ornamental structure emphasizes the natural architecture already present in the bone','A skeletal forearm aligns the radius and ulna with the wearers actual arm while the hand bones continue partially toward the wrist. Black and Grey shading creates a believable view beneath the skin without gore','A jawbone is isolated from the skull and enlarged as a sculptural object. Teeth sockets and the sweeping mandibular curve become the entire design','A sequence of vertebrae gradually rotates as it travels down the calf moving from anatomically precise bone into increasingly abstract geometric forms','A skeletal shoulder joint is positioned around the actual shoulder with the scapula clavicle and humeral head simplified into Fine Line anatomical structure','A complete human skeleton is compressed into a long vertical anatomical study that follows the side torso. The bodys natural S curve determines how the skeleton bends rather than forcing it into a straight textbook pose')
$cats['Skulls & Skeletons']['Skulls & Skeletons Skeletons In Motion'] = @('A skeleton runs at full sprint. Sketch studies show several faint earlier positions of the arms and legs while one final skeleton resolves in confident black','A skeleton dances alone with its spine curved one arm thrown overhead and one foot barely touching the ground. The posture communicates joy without turning the figure into a joke','A skeleton dives headfirst downward with arms extended and legs trailing behind. The long vertical body creates a natural forearm composition','Two skeletons dance together with their hands connected and bodies leaning away from one another. Engraving-style linework gives the movement an old-world quality','A skeleton climbs upward using the wearers arm as though it were a vertical cliff. Hands and feet grip implied edges created only through shadow and negative space','A skeleton swims underwater with the spine curved naturally and arms pulling through the stroke. Turquoise environmental light reflects across ivory bone','A skeleton falls backward through empty space with limbs spread and the skull tilted toward the viewer. Extreme perspective enlarges the nearest hand dramatically','A skeleton crawls forward on hands and knees with one hand enormously foreshortened toward the viewer. Deep Blackwork shadow beneath the ribs creates threatening depth','A skeleton performs a deep ballet extension with one leg raised high and the rib cage rotating in the opposite direction. Anatomical accuracy makes the impossible-looking elegance believable','A skeleton rides a galloping skeletal horse with both anatomies moving convincingly. Loose Sketch lines and black ink movement connect rider and animal into one violent forward gesture')
$cats['Skulls & Skeletons']['Skulls & Skeletons Medieval Engraving and Memento Mori'] = @('A skeleton king sits on an elaborate Gothic throne wearing a heavy crown. Woodcut-style hatching creates deep shadow while the pose remains solemn rather than monstrous','A skeleton carries a single burning candle through darkness. Engraving lines describe the bones while the candle provides one warm area of restrained gold and orange','A skeleton astronomer looks through an old telescope toward a field of engraved stars. The entire piece resembles an impossible Renaissance scientific plate','A skeleton kneels beneath an enormous Gothic cathedral arch. The architecture towers above the figure so scale and mortality become the visual relationship','A medieval knight is shown entirely as a skeleton inside damaged plate armor. The open visor reveals the skull while bone hands grip a long sword planted into the earth','Two skeletons embrace beneath a dead tree in dense woodcut hatching. Their pose remains tender while the visual language is dark and ancient','A skeleton sits at a writing desk surrounded by old books quill and candlelight. The image feels like a forgotten engraving about knowledge and time rather than a novelty skeleton scene','A skeleton climbs a narrow spiral staircase that disappears into black above it. Engraving lines become increasingly dense as the staircase rises','A skeleton lies beneath a tree while roots weave naturally through the rib cage and pelvis. Woodcut treatment makes bone earth and root part of the same material world','A memento mori composition places one beautifully engraved skull beside an extinguished candle and a single fallen petal. The arrangement is sparse deliberate and historically inspired rather than overloaded with symbols')
$cats['Skulls & Skeletons']['Skulls & Skeletons Blackwork Shadow and Negative Space'] = @('A human skull emerges from a nearly solid black field. One eye socket and half the jaw remain untouched skin while the opposite side disappears completely','A full skeleton walks out of a Blackwork field as though leaving darkness physically behind. The rear leg and one arm remain swallowed by black while the front half becomes increasingly defined','A skull is reduced to only the most essential black shapes of the sockets nasal cavity jaw and shadow. From a distance it reads immediately while close inspection reveals almost no conventional outline','A rib cage becomes a Negative Space composition where the bones remain natural skin and the spaces surrounding them become deep black','A skeletons lower body disintegrates into enormous black brush gestures while the skull ribs and hands remain anatomically detailed','A skull appears inside a solid black circle but is created almost entirely through negative skin. Only several tiny black anatomical details exist inside the bone itself','A skeletal hand reaches out from a Blackwork void with the nearest finger bones dramatically enlarged through perspective','A full skeleton curls inside a black crescent-shaped field. Portions of bone disappear wherever the body crosses the darkest areas forcing the viewer to complete the anatomy mentally','A skull and snake use almost no internal grey. Heavy black silhouette negative skin and carefully chosen white channels create both forms through graphic contrast','A skull is fragmented into irregular black and negative-space planes while remaining anatomically readable. The effect feels like a skull being reconstructed from shadow rather than ordinary geometry')
$cats['Skulls & Skeletons']['Skulls & Skeletons Color Light and Bone'] = @('An ivory skull is illuminated by cobalt light from one side and hot orange light from the other. The bone itself remains natural while reflected color completely changes the mood','A full skeleton stands beneath neon magenta and turquoise lighting as though outside a city at night. Colored reflections follow the actual planes of the bone rather than filling bones with arbitrary color','A skull sits beneath stained-glass light. Red cobalt violet and gold shapes cross the ivory bone while the skull itself remains realistically rendered','A skeleton floats underwater while blue-green light ripples across the ribs pelvis and skull. Small bubbles rise naturally through the open structure of the body','A cherry-red skeleton is rendered through New School dimensionality with exaggerated foreshortening but anatomically recognizable bones. Deep burgundy shadows prevent the color from becoming flat','A skull is surrounded by deep violet shadow while emerald light appears to originate inside the cranial cavity and escape through the eye sockets and teeth','A skeletal hand holds a brilliant orange butterfly. The bone remains muted ivory while the butterfly provides the only saturated color in the tattoo','A skull appears beneath rippling red water. The surface distorts the upper cranium while the jaw remains visible below in darker burgundy shadow','A skeleton sits beneath a brilliant sunset but only reflected warm light on the bones and a narrow atmospheric horizon establish the environment','A skull is rendered through Watercolour with precise anatomical linework holding the form while indigo crimson and ochre pigment moves through and beyond the bone structure')
$cats['Skulls & Skeletons']['Skulls & Skeletons Animal Bones and Other Skeletons'] = @('A complete snake skeleton curves naturally around the forearm. Hundreds of tiny vertebrae and ribs create a remarkable repeating structure without requiring additional imagery','A bird skeleton is shown in flight with both skeletal wings fully extended. Fine Line anatomy makes the fragile architecture of flight itself the artwork','A horse skeleton gallops at full speed. Sketch studies around the legs explore how skeletal anatomy behaves in motion rather than simply showing a museum specimen','A bat skeleton hangs upside down with wings partially folded around the body. Dense Dotwork behind it reveals the extraordinary finger-like structure supporting each wing','A whale skeleton descends through deep black water with a tiny human skeleton far below it. The contrast in skeletal scale becomes the entire composition','A ram skull and enormous horns are rendered as a sculptural Black and Grey study. The horns wrap naturally around the shoulder rather than sitting symmetrically on a flat plane','A crocodile skull is viewed from directly above. Fine anatomical detail emphasizes the long jaw teeth and unusual openings in the bone','A cat skeleton stretches with the spine arched and front legs extended. The familiar feline behavior remains instantly recognizable even without fur or facial expression','A shark jaw floats in deep water with several missing teeth and natural imperfections preserved. Cold blue environmental light reflects across the pale structure','A reconstructed prehistoric skeleton runs through a museum-like darkness but progressively gains muscle and living form toward the head as though the fossil is becoming the animal again')
$cats['Skulls & Skeletons']['Skulls & Skeletons Surreal Bone'] = @('A skull opens at the crown into an impossible spiral staircase descending through the cranium. A tiny figure stands halfway down the staircase establishing enormous internal scale','A skeletons rib cage contains a miniature stormy ocean. Waves move between the ribs while a tiny boat appears deep inside the chest cavity','A skulls eye socket becomes an architectural doorway leading into a long illuminated corridor. The skull remains realistic while the interior space violates physical scale','A Gothic cathedral grows vertically through the rib cage of a standing skeleton. Columns align with ribs while towers emerge behind the shoulders making anatomy and architecture share the same structure','A skeleton pulls itself upward from an identical skeleton lying beneath it as though escaping its own former body. Hands ribs and spines overlap in carefully controlled anatomical layers','The bones of a skeleton gradually become tree roots from the pelvis downward. Above the ribs branches begin emerging from the shoulder blades creating one continuous anatomical transformation','A skull contains a violent thunderstorm. Lightning flashes through one eye socket while dark clouds appear to occupy impossible depth inside the cranium','A skeleton stands beneath an enormous floating version of its own skull. The tiny full body looks upward while the giant skull fills most of the composition','A skull separates into thin vertical anatomical slices that drift gradually around the arm. Each slice remains part of one coherent skull when viewed from the primary angle','A full skeleton progressively disappears upward into a flock of dark birds. The pelvis and legs remain complete ribs begin fragmenting and the skull becomes the final point where bone turns into flight')
$cats['Skulls & Skeletons']['Skulls & Skeletons Push Skulls and Skeletons'] = @('A realistic womans face turns in profile across the outer thigh while portions of the cheek jaw and temple transition seamlessly into anatomically accurate skull. The transformation follows actual facial structure rather than splitting the face neatly in half. Warm living skin cold ivory bone and deep burgundy shadow create a beautiful confrontation between surface and structure','Two complete skeletons fall through an enormous empty vertical space while desperately reaching toward one another. One is closer to the viewer and dramatically foreshortened while the other appears much farther away. Their fingertips almost meet at the center making the entire tattoo about a tiny gap between two hands','A monumental skull becomes an entire ruined city. Teeth transform gradually into towers and streets pass through the eye sockets while tiny human figures establish scale. The transition is seamless enough that the viewer first sees a skull and only afterward discovers the architecture','A full skeleton sits peacefully at the bottom of the ocean while an enormous whale swims far above. The skeleton is small within the composition. Blue-green light descends through the water and tiny sea life has begun settling naturally among the ribs. The image feels peaceful rather than horrific','A skeleton rider charges forward on a skeletal horse through heavy rain. Extreme perspective makes the horses skull and front legs enormous while rider and rear body compress backward. Engraving anatomy collides with contemporary Blackwork and selective crimson reflected light','A human skeleton grows upward through the womans back like an impossible second internal body. The pelvis begins low vertebrae follow the spine and the rib cage expands naturally across the shoulder blades. At the shoulders the skeletal arms extend outward and gradually become enormous black wings built from bone-like structures rather than feathers','A gigantic skeletal hand reaches across the mans chest as though emerging from behind the body. The nearest finger bones use extreme foreshortening while the wrist disappears into a deep Blackwork void near the shoulder. Tiny architectural structures beneath the fingertips create impossible scale','Two skeletons embrace underwater while their bodies slowly separate into drifting bones. The upper bodies remain connected at the ribs and hands while individual vertebrae fingers and smaller bones rise around them in blue-green light. The image communicates love and loss without a single conventional memorial symbol','A human skull fractures open across the upper arm and reveals an entire night sky inside. The eye sockets remain absolute black while the broken cranium exposes impossible cosmic depth. A skeletal hand reaches from inside the skull toward the viewer creating a second layer of impossible scale','Create the ultimate Skulls and Skeletons composition across the full upper back. Two enormous skeletal figures occupy opposite sides of the body one reaching upward and one descending while their rib cages curve with the shoulder blades. Between them floats a colossal fragmented skull whose sections separate into architectural ruins tree roots black birds and geometric bone structures. A tiny living human figure stands inside one eye socket looking outward establishing impossible scale. Deep Blackwork anchors the composition while ivory bone crimson reflected light and subtle cobalt atmosphere create dimensional separation. Every transformation must grow logically from skeletal anatomy. The piece should feel simultaneously anatomical medieval surreal emotional and contemporary without becoming a random collage')
$b['An anatomically observed human skull is shown from an unusual three-quarter underside angle so the jaw teeth cheekbone and base of the cranium become the composition. Fine Black and Grey rendering treats the skull like a beautiful anatomical study rather than a death emblem'] = 'Two panels side by side on one image, divided down the middle. LEFT PANEL: the tattoo design alone on a plain white background, shown flat exactly as described, no body, drawn large so it fills most of the panel. RIGHT PANEL: Studio photograph of a real person''s body showing the same exact tattoo where described, healed tattoo on real skin in soft even light, the rest of the body modestly covered by simple plain clothing, only the tattooed area bare, plain seamless light grey studio backdrop - no room, no furniture, no scenery. The tattoo in both panels is identical. The tattoo: An anatomically observed human skull is shown from an unusual three-quarter underside angle so the jaw, teeth, cheekbone and base of the cranium become the composition. Fine Black and Grey rendering treats the skull like a beautiful anatomical study rather than a death emblem. Anatomical, intelligent, severe. In the right panel it is on a man, outer forearm. Create exceptional contemporary tattoo inspiration centered on skulls, skeletons and bone. BONE IS THE MATERIAL. DEATH IS NOT THE ONLY SUBJECT. Skulls and skeletons can express: Anatomy. Death. Life. Movement. Love. Loneliness. Strength. Fear. Beauty. Time. Nature. Science. History. Transformation. Darkness. Faith. Architecture. And pure fascination with skeletal form. UNDERSTAND THE DIFFERENCE BETWEEN A SKULL AND A SKELETON. A skull is primarily a form. Study it. Rotate it. Light it. Fracture it. Abstract it. Open it. Reconstruct it. Transform it. Use unusual anatomical viewpoints. Do not default to a centered front-facing skull. A skeleton is a body. USE BODY LANGUAGE. Skeletons can: Walk. Run. Dance. Fight. Pray. Reach. Fall. Climb. Embrace. Protect. Carry. Swim. Ride. Rest. Lie down. Curl inward. Stretch upward. Skeletons do not need facial expression to communicate emotion. Posture is the expression. ANATOMY MATTERS. When anatomy is presented as realistic or scientific, respect actual skeletal structure. Understand: Skull. Jaw. Teeth. Spine. Vertebrae. Rib cage. Scapula. Clavicle. Pelvis. Humerus. Radius. Ulna. Hands. Femur. Tibia. Fibula. Feet. Do not accidentally invent random bones. Do not create impossible joints unless distortion is intentionally part of the artwork. Artistic transformation is welcome. Anatomical mistakes are not artistic transformation. USE THE HUMAN BODY. Bone is uniquely suited to body-aware tattoo composition. A skeletal hand can interact with the real hand. Vertebrae can follow the spine. Ribs can interact with the torso. A shoulder joint can relate to the actual shoulder. A jaw can follow anatomical curves. A skeleton can climb an arm. A skull can rotate around a shoulder. A skeleton can curl around a thigh. Do not simply place anatomical diagrams onto skin. THE BODY CAN BECOME PART OF THE ANATOMICAL IDEA. USE THE FULL WORLD OF TATTOOING. Black and Grey Realism. Fine Line. Dotwork. Blackwork. Sketch. Engraving. Woodcut. Illustrative. Neo-Traditional. American Traditional. New School. Geometric. Negative Space. Watercolour. Colour Realism. Surrealism. Ornamental. And intelligent combinations. Do not mechanically rotate styles. Choose the artistic language that makes the idea stronger. MEDIEVAL AND ENGRAVING WORK SHOULD FEEL AUTHENTICALLY DRAWN. Use: Cross-hatching. Parallel engraving lines. Woodcut texture. Dense directional shading. Old anatomical illustration. Memento mori. Gothic architecture. Medieval figures. Historical visual language. Do not merely apply a vintage filter to modern clip art. BLACKWORK SHOULD USE BLACK AS STRUCTURE. Allow bone to emerge from darkness. Use natural skin as bone. Use negative space. Allow sections of anatomy to disappear. Use large black fields when appropriate. Use brush gestures. Use silhouette. Do not simply shade every skull dark grey. FINE LINE SHOULD REMAIN ARTISTICALLY AMBITIOUS. Fine Line skulls do not need flowers. Explore unusual anatomical angles. Skeletal hands. Spines. Pelvis. Movement. Full skeletons. Relationships between figures. Scientific drawing. Construction. COLOR IS WELCOME. Bone does not need to be painted random colors. Color can come from light. Neon. Water. Fire. Stained glass. Sunset. Reflections. Atmosphere. Environmental light. Ivory bone can receive: Cobalt light. Crimson light. Emerald light. Violet shadow. Turquoise underwater reflection. Warm gold. Color should make physical or artistic sense. Do not turn every colorful skull into a sugar skull. DIA DE LOS MUERTOS AND CALAVERA IMAGERY HAVE SPECIFIC CULTURAL CONTEXT. Treat those traditions accurately and respectfully when intentionally used. Do not use Mexican cultural imagery merely as generic colorful skull decoration. ANIMAL SKELETONS BELONG. Explore: Bird skeletons. Snake skeletons. Bat skeletons. Horse skeletons. Whale skeletons. Ram skulls. Deer skulls. Crocodile skulls. Shark jaws. Prehistoric skeletons. Other fascinating skeletal anatomy. Do not simply repeat the Animals category with bones. The skeletal structure itself should be the artistic reason for the design. SURREALISM CAN GO FAR. A skull can contain architecture. An eye socket can become a doorway. A rib cage can contain an ocean. A skeleton can become roots. A skull can contain a storm. Bone can become birds. Bone can become architecture. Bone can become geometry. A skeleton can escape another skeleton. A skull can separate into layers. Scale can become impossible. But maintain visual hierarchy. Do not create random surreal collage. THE SKULL OR SKELETON MUST REMAIN THE HERO. DARKNESS IS WELCOME. Do not make everything dark. Do not make everything beautiful. Do not make everything aggressive. Do not make everything solemn. Bone can be: Quiet. Romantic. Scientific. Sexual. Tender. Brutal. Elegant. Terrifying. Peaceful. Funny when intentionally appropriate. Ancient. Futuristic. Minimal. Monumental. THE CLICHES ARE ALLOWED. THE CLICHES ARE NOT ALLOWED TO CONTROL THE CATEGORY. Skull and rose. Skull and snake. Skull and crown. Skull and dagger. Skull and moth. Skull and clock. These are established tattoo subjects. Use them when the design is genuinely exceptional. Do not produce endless variations because they are easy. Do not surround every skull with flowers. Do not put a crown on every skull. Do not put a snake through every eye socket. Do not make every skeleton a grim reaper. Do not make every skeleton comedic. Do not make every skull realistic. Do not make every design Black and Grey. Do not make every skull face forward. Do not make every skeleton stand upright. Do not make everything about death. BONE IS THE MATERIAL. THE ART CAN GO ANYWHERE'
