foreach ($c in $cats.Keys) { foreach ($k in $cats[$c].Keys) { $h = @($got2.tree.specific.$k | ? { $_ }).Count; if ($h -ne $cats[$c][$k].Count) { "  STILL SHORT: " + $k + " has " + $h; $short++ } } }
